messages.content:
Tool response:
Tool: reassign_task
Description: Reassign Task
Parameters:
    {
      "type": "object",
      "properties": {
        "task_id": {
          "type": "integer",
          "description": "Internal ID of the task to reassign",
          "title": "Task Id"
        },
        "assigned_to_user_id": {
          "type": "integer",
          "title": "Assigned To User Id",
          "description": "Internal ID of the new assignee (must be an eligibility specialist)"
        },
        "escalation_reason": {
          "type": "string",
          "title": "Escalation Reason",
          "description": "Reason for escalation (e.g., 'Pending 48-hour SLA breach')"
        },
        "new_due_date": {
          "type": "string",
          "title": "New Due Date",
          "description": "New due date in ISO 8601 format (e.g., 2024-05-22T17:00:00Z)"
        }
      },
      "required": [
        "task_id",
        "assigned_to_user_id",
        "escalation_reason",
        "new_due_date"
      ]
    }
